record.field:
{
  "@context": "https://schema.org",
  "@type": "Organization",
  "@id": "{{ site_url }}/#organization",
  "name": "{{ company.name | default("") }}",
  "legalName": "{{ settings.legal_name | default("") }}",
  "url": "{{ site_url }}/",
  "logo": {
    "@type": "ImageObject",
    "url": "{{ settings.logo_url | default("") }}"
  },
  "description": "{{ record.seo_description | default("") }}",
  "address": {
    "@type": "PostalAddress",
    "streetAddress": "{{ company.street | default("") }}",
    "addressLocality": "{{ company.city | default("") }}",
    "addressCountry": "{{ company.country_id.code | default("") }}"
  },
  "areaServed": "{{ company.country_id.name | default("") }}",
  "sameAs": {{ company.get_era_seo_social_profiles_json | json }},
  "foundingDate": "{{ settings.founding_date | default("") }}",
  "knowsAbout": {{ company.get_era_seo_knows_about | json }}
}

{
  "@context": "https://schema.org",
  "@type": "WebSite",
  "@id": "{{ site_url }}/#website",
  "url": "{{ site_url }}/",
  "name": "{{ website.name | default("") }}",
  "description": "{{ record.seo_description | default("") }}",
  "publisher": {
    "@id": "{{ site_url }}/#organization"
  },
  "potentialAction": {
    "@type": "SearchAction",
    "target": {
      "@type": "EntryPoint",
      "urlTemplate": "{{ site_url }}/search?q={search_term_string}"
    },
    "query-input": "required name=search_term_string"
  }
}

{
  "@context": "https://schema.org",
  "@type": "MobileApplication",
  "name": "{{ record.seo_title | default("") }}",
  "description": "{{ record.seo_description | default("") }}",
  "url": "{{ record.seo_canonical_url | default("") }}",
  "image": "{{ record.seo_og_image_url | default("") }}",
  "operatingSystem": "ANDROID, IOS",
  "applicationCategory": "BusinessApplication",
  "offers": {
    "@type": "Offer",
    "price": "0",
    "priceCurrency": "USD"
  },
  "publisher": {
    "@type": "Organization",
    "@id": "{{ site_url }}/#organization",
    "name": "{{ company.name | default("") }}"
  }
}

{
  "@context": "https://schema.org",
  "@type": "SoftwareApplication",
  "name": "{{ record.seo_title | default("") }}",
  "description": "{{ record.seo_description | default("") }}",
  "url": "{{ record.seo_canonical_url | default("") }}",
  "image": "{{ record.seo_og_image_url | default("") }}",
  "applicationCategory": "BusinessApplication",
  "operatingSystem": "Web",
  "offers": {
    "@type": "Offer",
    "price": "0",
    "priceCurrency": "USD"
  },
  "publisher": {
    "@type": "Organization",
    "@id": "{{ site_url }}/#organization",
    "name": "{{ company.name | default("") }}"
  }
}

{
  "@context": "https://schema.org",
  "@type": "Article",
  "headline": "{{ record.seo_title | default("") }}",
  "description": "{{ record.seo_description | default("") }}",
  "image": "{{ record.seo_og_image_url | default("") }}",
  "url": "{{ record.seo_canonical_url | default("") }}",
  "publisher": {
    "@type": "Organization",
    "@id": "{{ site_url }}/#organization",
    "name": "{{ company.name | default("") }}",
    "logo": {
      "@type": "ImageObject",
      "url": "{{ settings.logo_url | default("") }}"
    }
  },
  "author": {
    "@type": "Organization",
    "name": "{{ company.name | default("") }}"
  },
  "mainEntityOfPage": {
    "@type": "WebPage",
    "@id": "{{ record.seo_canonical_url | default("") }}"
  }
}

{
  "@context": "https://schema.org",
  "@type": "BlogPosting",
  "headline": "{{ record.seo_title | default("") }}",
  "description": "{{ record.seo_description | default("") }}",
  "image": "{{ record.seo_og_image_url | default("") }}",
  "url": "{{ record.seo_canonical_url | default("") }}",
  "publisher": {
    "@type": "Organization",
    "@id": "{{ site_url }}/#organization",
