    "logo": {
      "@type": "ImageObject",
      "url": "{{ settings.logo_url | default("") }}"
    }
  },
  "author": {
    "@type": "Organization",
    "name": "{{ company.name | default("") }}"
  },
  "mainEntityOfPage": {
    "@type": "WebPage",
