{
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    {
      "@type": "ListItem",
      "position": 1,
      "name": "{{ website.name | default("Home") }}",
      "item": "{{ site_url }}/"
    },
    {
      "@type": "ListItem",
      "position": 2,
      "name": "{{ record.seo_title | default("") }}",
      "item": "{{ record.seo_canonical_url | default("") }}"
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "Product",
  "name": "{{ record.seo_title | default("") }}",
  "description": "{{ record.seo_description | default("") }}",
  "image": "{{ record.seo_og_image_url | default("") }}",
  "url": "{{ record.seo_canonical_url | default("") }}",
  "brand": {
    "@type": "Brand",
    "name": "{{ company.name | default("") }}"
  },
  "offers": {
    "@type": "Offer",
    "priceCurrency": "SAR",
    "price": "0",
    "availability": "https://schema.org/InStock",
    "seller": {
      "@type": "Organization",
      "name": "{{ company.name | default("") }}"
    }
  }
}

{
  "@context": "https://schema.org",
  "@type": "Person",
  "name": "{{ record.seo_title | default("") }}",
  "description": "{{ record.seo_description | default("") }}",
  "image": "{{ record.seo_og_image_url | default("") }}",
  "url": "{{ record.seo_canonical_url | default("") }}",
  "worksFor": {
    "@type": "Organization",
    "@id": "{{ site_url }}/#organization",
    "name": "{{ company.name | default("") }}"
  }
}
